// Kontrollerar F3: hopplänken är första fokuserbara element, pekar på <main id="app">, CSS:en är AI-märkt,
// och klicket flyttar fokus utan att ändra adressens hash (sajten växlar vy på hash).
// AI-skapat (B-051). Generated by AI, Directed by MS.
const fs = require('fs');
const css = fs.readFileSync('public/css/hoppa.css', 'utf8');
const html = fs.readFileSync('public/index.html', 'utf8');
// index.html har ingen uttrycklig <body>-tagg; innehållet börjar efter sista </style> i sidhuvudet.
const body = html.includes('<body') ? html.split(/<body[^>]*>/)[1] : html.slice(html.indexOf('</style>') + 8);
const forstaLank = (body.match(/<a\b[^>]*>/) || [''])[0];
const krav = {
  forstFokus: /class="hoppa"/.test(forstaLank) && /href="#app"/.test(forstaLank),
  malFinns: /<main[^>]+id="app"/.test(html),
  malFokuserbart: /<main[^>]+tabindex="-1"/.test(html),
  lankad: html.includes('/css/hoppa.css'),
  doldTillsFokus: /\.hoppa:focus/.test(css) && /top:\s*-4rem/.test(css),
  svenskText: body.includes('Hoppa till innehållet'),
  aiMarkt: css.includes('Generated by AI, Directed by MS'),
  roraInteHash: /querySelector\('\.hoppa'\)\.addEventListener\('click',e=>\{e\.preventDefault\(\)/.test(html),
};
const ok = Object.values(krav).every(Boolean);
console.log(JSON.stringify({ ...krav, ok }));
process.exit(ok ? 0 : 1);
